contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(c).balance >= amount, "insufficient balance in c");

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;
        uint callerBalanceBefore = address(this).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;
        uint callerBalanceAfter = address(this).balance;

        assert(
            !reverted &&
            ownerAfter == ownerBefore &&
            depositsAfter == depositsBefore &&
            balanceAfter == balanceBefore - amount &&
            callerBalanceAfter == callerBalanceBefore + amount
        );
    }

    receive() external payable {}
}

